import ast,base64,json,hashlib,copy
d=json.loads(base64.b64decode(""))
checks=[]
def ck(n,v):
 if not v:raise AssertionError(n)
 checks.append(n)
a,b=ast.parse(d["before"]),ast.parse(d["after"])
dump=lambda x:ast.dump(x,include_attributes=False)
assigns=lambda m:{n.targets[0].id:n for n in m.body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
aa,bb=assigns(a),assigns(b)
ck("same_top_level_assignments",set(aa)==set(bb))
ck("only_ready_false_to_true",ast.literal_eval(aa["BINDING_READY"].value) is False and ast.literal_eval(bb["BINDING_READY"].value) is True)
old,actual=ast.literal_eval(aa["FILES"].value),ast.literal_eval(bb["FILES"].value)
ck("seven_rows_same_order",len(old)==len(actual)==7)
for i,(x,y,info) in enumerate(zip(old,actual,d["infos"],strict=True)):
 ck("input%d_original_fixed_path_and_name"%i,x["path"]==y["path"]==info["path"] and x["name"]==y["name"])
 ck("input%d_only_original_three_nulls_bound"%i,set(x)==set(y) and all(x[k] is None for k in ["bytes","sha256","version"]) and all(x[k]==y[k] for k in x if k not in ["bytes","sha256","version"]))
 ck("input%d_exact_actual_identity_pins"%i,y["bytes"]==info["size"] and y["sha256"]==info["sha256"] and y["version"]==info["version"] and y["source_mode"]==info["mode"] and y["target_mode"]==(320 if i==0 else 256))
defs=lambda m:{n.name:n for n in m.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))}
ad,bd=defs(a),defs(b)
ck("same_definition_names",set(ad)==set(bd))
ck("original_definition_count",len(ad)==d["expected_definitions"])
for n in ad:ck(n+"_complete_definition_bytes_identical",ast.get_source_segment(d["before"],ad[n])==ast.get_source_segment(d["after"],bd[n]))
normalized=copy.deepcopy(b)
allow=["FILES","BINDING_READY"]
if d["role"]=="relay":
 oldhelpers=ast.literal_eval(aa["HELPERS"].value);helpers=ast.literal_eval(bb["HELPERS"].value)
 ck("only_two_derived_helper_keys",set(oldhelpers)==set(helpers)=={"sender.py","receiver.py"})
 ck("actual_final_helper_SHA_pins",helpers==d["final_helper_pins"])
 ck("original_source36_helper_SHA_pins",oldhelpers==d["original_helper_pins"])
 allow.append("HELPERS")
for n in normalized.body:
 if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id in allow:n.value=copy.deepcopy(aa[n.targets[0].id].value)
ck("whole_AST_identical_after_only_input_ready_helper_literals",dump(normalized)==dump(a))
ck("all_other_top_level_statements_byte_identical",all(ast.get_source_segment(d["before"],x)==ast.get_source_segment(d["after"],y) for x,y in zip(a.body,b.body,strict=True) if not(isinstance(x,ast.Assign) and len(x.targets)==1 and isinstance(x.targets[0],ast.Name) and x.targets[0].id in allow)))
print(json.dumps({"schema":"heptabao.root-X230-ready-role-actual-binding-AST.r30.v1","status":"PASS_SOURCE_ONLY","role":d["role"],"checks_passed":len(checks),"checks":checks,"whole_definition_count_unchanged":len(ad),"input_literals":21,"ready_literal":1,"derived_helper_literals":2 if d["role"]=="relay" else 0,"before_bytes":len(d["before"].encode()),"after_bytes":len(d["after"].encode()),"after_sha256":hashlib.sha256(d["after"].encode()).hexdigest(),"old_fences_and_deadlines_unchanged":True,"candidate_executed":False,"Runtime_calls":0,"X230_qualified":False},sort_keys=True))
